import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import java.util.function.Consumer;

public class GenericObjectPool<T> {
    private final BlockingQueue<T> pool;
    private final Supplier<T> factory;
    private final Consumer<T> resetter;

    public GenericObjectPool(int capacity, Supplier<T> factory, Consumer<T> resetter) {
        this.factory = factory;
        this.resetter = resetter;
        this.pool = new LinkedBlockingQueue<>(capacity);
        for (int i = 0; i < capacity; i++) {
            pool.offer(factory.get());
        }
    }

    public T borrowObject(long timeout, TimeUnit unit) throws InterruptedException {
        T instance = pool.poll(timeout, unit);
        if (instance == null) {
            throw new IllegalStateException("Timeout waiting for object from pool.");
        }
        return instance;
    }

    public void returnObject(T instance) {
        if (instance != null) {
            resetter.accept(instance);
            if (!pool.offer(instance)) {
                // Pool is full, allow GC to collect the overflow instance
            }
        }
    }
}
